python3 -c "
import json
with open('/app/resources/treasury_bulletin_1980_05.json', 'r') as f:
    data = json.load(f)
# Find keys that might contain CPI data
def find_keys(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            yield k
            yield from find_keys(v, f'{path}.{k}')
    elif isinstance(d, list):
        pass

keys = list(find_keys(data))
for k in keys:
    if 'cpi' in k.lower() or 'price' in k.lower() or 'consumer' in k.lower():
        print(k)
